//! Protobuf types for the Stellar foundational modules.
//!
//! Generated by the `buf.build/anthropics/buffa` plugin; run `substreams protogen` to regenerate.

macro_rules! include_buffa {
    ($package:literal) => {
        include!(concat!($package, ".mod.rs"));
    };
}

pub mod sf {
    pub mod stellar {
        pub mod r#type {
            pub mod v1 {
                include_buffa!("sf.stellar.type.v1");
            }
        }
    }

    pub mod substreams {
        pub mod stellar {
            pub mod r#type {
                pub mod v1 {
                    include_buffa!("sf.substreams.stellar.type.v1");
                }
            }
        }
    }
}
